ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS description TEXT;
UPDATE public.categories SET slug='industrial', description='<p dir="ltr">CTE Skills&#39;<strong>&nbsp;</strong>Industrial Video Course library&nbsp;offered for Online Skills Training include the following categories: Analyzers, Electrical, Instrumentation, Process Technology and Mechanical. With your Subscription to CTESkills.com&rsquo;s industrial training video library you have access to your videos 24/7 anywhere you have internet &nbsp;access.</p>' WHERE slug='industrial' AND name='Industrial';
UPDATE public.categories SET slug='buildings-trades', description='CTE Skills&#39; Buildings and Trades Video library offered for Online Skills Training include the following videos: Steel Framing Square, Common Types of&nbsp;Roofing and The Common Rafter&nbsp;. These courses videos offer&nbsp;basic knowledge and practical experience in various aspects of the construction trades' WHERE slug='buildings-and-trades' AND name='Buildings and Trades';
UPDATE public.categories SET slug='cosmetology', description='CTE Skills&#39;<strong>&nbsp;</strong>Cosmetology Video library&nbsp;offered for Online Skills Training helps students learn techniques and practices needed to pass their state board cosmetology exam.&nbsp;With your Subscription to CTESkills.com&rsquo;s industrial training video library you have access to your videos 24/7 anywhere you have internet access.' WHERE slug='cosmetology' AND name='Cosmetology';
UPDATE public.categories SET slug='criminal-justice', description='The Criminal Justice program focuses on the criminal justice system; including instruction in criminal law and policy, police and correctional systems organization, the administration of justice and the judiciary, and the public attitudes regarding criminal justice. <p>CTE Skills&#39; Criminal Justice&nbsp;Training&nbsp;Video category offered for Online Skills Training include topics such as: Clearing a Building, Hand Cuffing Techniques, Felony Traffic Stop and Domestic Dispute. These video&nbsp;courses offer&nbsp;basic knowledge and practical experience in various aspects of Criminal Justice.&nbsp;With your Subscription to CTESkills.com&rsquo;s Criminal Justice training video library you have access to your videos 24/7.' WHERE slug='criminal-justice' AND name='Criminal Justice';
UPDATE public.categories SET slug='health-science', description='Purchase access to the entire Health Science category and get access to over 50 detailed videos. CTE Skills&#39;<strong>&nbsp;</strong>Health Science video course library&nbsp;offered for Online Skills Training include the following categories: CNA, Anatomy and Physiology, and Medical Terminology.&nbsp;With your Subscription to CTESkills.com&rsquo;s Health Sciences Technologies &nbsp;training video library you have access to your videos 24/7 anywhere you have internet &nbsp;access.' WHERE slug='health-science' AND name='Health Science';
UPDATE public.categories SET slug='hvac', description='<p>The HVAC category covers a variety tasks typical to the Heating, Ventilation and Air Conditioning field.</p><p>CTE Skills&#39; HVAC Training Video category offered for Online Skills Training include topics such as: Manifold Gauge Set, Recovery and Pump Down, Soap Leak Check, Electronic Leak Check, Evacuation, Liquid Charging, Vapor Charging and Compressors and many more to come.</p><p>In addition to the specific tasks featured in this CTE category, we also offer a series of videos that present basic, entry level information pertaining to the HVAC Industry. In these videos you will learn about Air Flow and how it relates to the Duct and System Design as well as the standard components you&rsquo;ll find within an HVAC system.</p>' WHERE slug='hvac' AND name='HVAC';
UPDATE public.categories SET slug='mobile-equipment', description='<p>The Mobile Equipment video category includes the classroom portion with visual examples of how to operate certain equipment such as a Carry Deck Cranes, Aerial Lifts and Forklifts.&nbsp;The Mobile Equipment training course is appropriate for basic training or as a refresher for experienced professionals.</p><p>CTE Skills&#39; Mobile Equipment Training&nbsp;Video category offers basic knowledge and practical experience for safe operations of this equipment. With your Subscription to CTESkills.com&rsquo;s Mobile Equipment&nbsp;training video library you have access to your videos 24/7.</p>' WHERE slug='mobile-equipment' AND name='Mobile Equipment';
UPDATE public.categories SET slug='utility-line-tech', description='The Utility Line Technician video category prepares students to work in the power line industry as an apprentice lineman. It&#39;s not only appropriate for basic training but it works great as a refresher for the experienced professional as well. CTE Skills&#39; Utility Lineman&nbsp;Training&nbsp;Video category offered for Online Skills Training include topics such as: Pole Top and Bucket Rescue, Transformer Overviews and Installation procedures, Pole Setting, Pole Climbing Techniques and more.' WHERE slug='utility-line-technician' AND name='Utility Line Technician';
UPDATE public.categories SET slug='welding', description='Welding involves various processes of joining metal together. CTE Skills&#39; Welding Training Video category provides you with efficient and safe techniques used in modern welding applications. This series also covers identification and operation of welding equipment as well as proper safety procedures and PPE involved.' WHERE slug='welding' AND name='Welding';
UPDATE public.categories SET slug='computers', description='<p>CTE Skills&#39; Computers&nbsp;Training&nbsp;Video category offered for Online Skills Training include the following videos: Computer Basics /Hardware&nbsp;and Hard Drives. These video&nbsp;courses offers basic knowledge and practical experience in various aspects of computers and their hardware.&nbsp;With your Subscription to CTESkills.com&rsquo;s Computer training video library you have access to your videos 24/7 anywhere you have internet access.</p>' WHERE slug='computers' AND name='Computers';
UPDATE public.categories SET slug='analyzers', description='<p>The Analyzer&nbsp;video training courses have&nbsp;been developed for anyone involved in the design, building, operation, or maintenance of process analyzer sampling systems. The Analyzer video training courses are appropriate for basic training or as a refresher for experienced professionals.</p>' WHERE slug='analyzers' AND name='Analyzers';
UPDATE public.categories SET slug='electrical', description='<p>The Electrical video training courses have been developed for anyone involved in the design, building, operation, or maintenance of any electrical systems or any equipment that operates with electricity. The Electrical video training courses are appropriate for basic training or as a refresher for experienced professionals.</p>' WHERE slug='electrical' AND name='Electrical';
UPDATE public.categories SET slug='instrumentation', description='<p>The Instrumentation course is built with the instrument technician in mind. This series of videos will give a better understanding of the operation, uses and even procedures of different instruments within the process industry. The training course is appropriate for basic training or as a refresher for experienced professionals.</p>' WHERE slug='instrumentation' AND name='Instrumentation';
UPDATE public.categories SET slug='process-technology', description='<p>The Process Technology video training course library&nbsp;has been developed to give a better understanding of Process Technology equipment and systems. In these videos we cover basic operation of specific equipment to understanding of the complex systems involved. The Process Technology training courses are appropriate for basic training or as a refresher for experienced professionals.</p>' WHERE slug='process-technology' AND name='Process Technology';
UPDATE public.categories SET slug='cosmetology-state-board', description='CTE Skills&#39;&nbsp;Cosmetology Training Video category offered for Online Skills Training features the 13 essential tests you will need to pass in order to be licensed. These include Bleach Retouch, Blow Dryer and Curling Iron Service, Chemical Application, End of Exam Disinfection, facial Service, Hair Shaping, Manicure, Mock Virgin Relaxer, On Base Roller Placement, Permanent Waving, Shampoo Service, State Board Preparation and Virgin Tint to Dark.' WHERE slug='cosmetology-state-board-license' AND name='Cosmetology - State Board License';
UPDATE public.categories SET slug='anatomy-physiology', description='Anatomy is the study of the structure and relationship between body parts. Physiology is the study of the function of body parts and the body as a whole. The goal of this CTE Skills Anatomy and Physiology video series is to present a full understanding of the functioning of the human body. To accomplish this, Anatomy and Physiology will be explained in three separate categories. Basic Cell Structure, Mapping of the Body, and a detailed explanation of the Body Systems.' WHERE slug='anatomy-and-physiology' AND name='Anatomy & Physiology';
UPDATE public.categories SET slug='cna', description='The CTE Skills CNA video category has been developed to aid those who may be pursuing a career as a Certified Nursing Assistant. These videos are designed to help a student pass the exams required in order to be licensed as a CNA.' WHERE slug='cna' AND name='CNA';
UPDATE public.categories SET slug='medical-terminology', description='The Medical Terminology video series is an&nbsp;<strong>easily accessible and affordable&nbsp;</strong>online program developed to facilitate the learning experience for medical terms. The Medical Terminology presented in this series complies&nbsp;with the CTE (Career and Technology Education) guidelines as required by the Education Agency of Texas. Any person seeking to learn and/or review the basics of medical terminology will greatly benefit from this&nbsp;video series.' WHERE slug='medical-terminology' AND name='Medical Terminology';
UPDATE public.categories SET slug='compressors', description='The Compressors video training courses are appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='compressors' AND name='Compressors';
UPDATE public.categories SET slug='pumps', description='The Pumps video training courses are appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='pumps' AND name='Pumps';
UPDATE public.categories SET slug='valves', description='The Valves video training courses are appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='valves' AND name='Valves';
UPDATE public.categories SET slug='cooling-towers', description='The Cooling Towers video training courses are appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='cooling-towers' AND name='Cooling Towers';
UPDATE public.categories SET slug='mechanical', description='The Mechanical video category has been developed to show specific procedures on certain equipment. These videos provide step by step procedures on how to perform these tasks. The Mechanical training course is appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='mechanical' AND name='Mechanical';
UPDATE public.categories SET slug='distillation', description='The Distillation video training courses are appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='distillation' AND name='Distillation';
UPDATE public.categories SET slug='process-equipment', description='The Introduction to Process Technology Equipment video training courses are appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='intro-to-process-equipment' AND name='Intro to Process Equipment';
UPDATE public.categories SET slug='cell-structure', description='In this series we will learn about the human cell structures and their specific functions each must perform and complete in order for the Human organism to stay alive and healthy throughout its expected &quot;Life Cycle&quot;. In addition we will discuss the &quot;disease process&quot; which is essentially a dysfunction that can occur at any time when any of the six basic functions of a healthy organism is negatively impacted.' WHERE slug='cell-structure' AND name='Cell Structure';
UPDATE public.categories SET slug='mapping-the-body', description='Mapping of the body is extremely important to anyone in the Health Sciences or medical fields. Whether you are a nurse aide or a surgeon, you need to understand the body in order to care for a patient properly. Views, body planes and directional terms will the first of two videos in this Mapping the Body series. In the next video we will cover the Body Cavities, Quadrants and regions.' WHERE slug='mapping-the-body' AND name='Mapping the Body';
UPDATE public.categories SET slug='body-systems', description='This series is currently in production and we will be releasing each video upon completion as we work towards a comprehensive digital teaching aid to assist in the instruction of Anatomy and Physiology.' WHERE slug='the-twelve-body-systems' AND name='The Twelve Body Systems';
UPDATE public.categories SET slug='basic-instrumentation', description='The Instrumentation course is built with the instrument technician in mind. This series of videos will give a better understanding of the operation, uses and even procedures of different instruments within the process industry. The training course is appropriate for basic training or as a refresher for experienced professionals.' WHERE slug='basic-instrumentation' AND name='Basic Instrumentation';
UPDATE public.categories SET slug='tube-bending', description='You become more efficient when bending tubing. There is more to tube bending than just bending, however. In order for proper and safe operation a technician should have a basic understand of tube fabrication, fitting makeup, and the importance of precision in bending the tube. In this CTE series on Tube Bending, we&rsquo;ll cover topics such as Tube Selection and Design, Tube Cutting Methods, Tube Bending Preparations, Proper Use of the Bending Tool, Making the Actual Bend, Bend Direction Marks, Tube Gain and Tube Gain Calculations, Changing Planes and Tube Orientation, as well as Fitting Types and Assembly.' WHERE slug='tube-bending-and-fittings' AND name='Tube Bending and Fittings';
UPDATE public.categories SET slug='calibration', description='<p>Calibration of Instrumentation key component for ensuring the accuracy of the equipment being used within any process industry. Calibration is the process by which the predetermined range of measurements are set for an individual instrument. In this CTE video category we offer detailed explantions of how to calibrate various types of instruments.</p>' WHERE slug='calibration' AND name='Calibration';
UPDATE public.categories SET slug='maintenance', description='The primary job for and Instrument Technician is maintenance. Maintenance is described as the care or upkeep of any piece of equipment or property. This CTE video category will display various tasks performed on different types of instrumentation within industry.' WHERE slug='maintenance' AND name='Maintenance';
UPDATE public.categories SET slug='hvac-basics', description='The Heating Ventilation and Air Conditioning (HVAC) field is growing and we have a shortage of good technicians to handle this work. In this CTE video beginner series on HVAC we will tackle some of the topics neccesary to understand in order to work in this field. We will begin by taking a look at Air Flow, Ducts and System design.' WHERE slug='hvac-basics' AND name='HVAC Basics';
UPDATE public.categories SET slug='hvac-performance', description='The HVAC category covers a variety tasks typical to the Heating, Ventilation and Air Conditioning field. CTE Skills&#39; HVAC Training Video category offered for Online Skills Training include topics such as: Manifold Gauge Set, Recovery and Pump Down, Soap Leak Check, Electronic Leak Check, Evacuation, Liquid Charging, Vapor Charging and Compressors and many more to come.' WHERE slug='hvac-performance-tasks' AND name='HVAC Performance Tasks';
UPDATE public.categories SET slug='duct-system-design', description='<p>The Heating Ventilation and Air Conditioning (HVAC) field is growing and we have a shortage of good technicians to handle this work. In this CTE video beginner series on HVAC, we will begin by taking a look at Air Flow, Ducts and System design. This seems to be one of the most misunderstood areas in this industry.</p>' WHERE slug='duct-and-system-design' AND name='Duct and System Design';
UPDATE public.categories SET slug='hvac-components', description='Being an HVAC Technician sometimes requires you to be more than just that. In this field you will need to be part plumber, part electrician, part carpenter, and even a customer service rep. While it is important to understand proper air flow, as well as duct and system design, it is equally important to understand each device that makes up an air system.' WHERE slug='hvac-components-and-parts' AND name='HVAC Components and Parts';